<?php
require '../config/config.php'; role('anggota');$uid=$_SESSION['u']['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$code=trim($_POST['copy_code']??'');if(!$code)throw new Exception('Masukkan atau scan barcode buku.');$q=$pdo->prepare("SELECT l.*,c.code,b.title FROM loans l JOIN copies c ON c.id=l.copy_id JOIN books b ON b.id=c.book_id WHERE l.user_id=? AND c.code=? AND l.returned_at IS NULL");$q->execute([$uid,$code]);$l=$q->fetch();if(!$l)throw new Exception('Buku dengan barcode tersebut tidak sedang Anda pinjam.');$d=$l['due_date']<date('Y-m-d')?(new DateTime($l['due_date']))->diff(new DateTime(date('Y-m-d')))->days:0;$f=$d*(int)setting('fine_per_day',500);$pdo->beginTransaction();$pdo->prepare('UPDATE loans SET returned_at=NOW(),late_days=?,fine=? WHERE id=?')->execute([$d,$f,$l['id']]);$pdo->prepare("UPDATE copies SET status='tersedia' WHERE id=?")->execute([$l['copy_id']]);$pdo->commit();setmsg("Buku berhasil dikembalikan. Denda: Rp".number_format($f,0,',','.'));header('Location:dashboard.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();setmsg($e->getMessage(),'danger');}
}
?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Kembalikan Buku</title><link rel=stylesheet href=../public/style.css></head><body><?php include 'nav.php'; ?><main style="max-width:1100px;margin:0 auto;padding:24px"><h1>↩️ Kembalikan Buku</h1><?php msg()?><div class=form><h3>Scan Barcode Buku</h3><p>Scan barcode eksemplar yang sedang Anda pinjam.</p><form method=post><label>Barcode Buku</label><input name=copy_code autofocus required placeholder="Scan barcode di sini"><button>↩️ Proses Pengembalian</button></form></div></main></body></html>
